window.docContents[84].resolve({"/Hoare/#assn-delaborators":{"contents":"As in the Imp chapter, the assertion notations\nabove are input only: Lean reads {{ X ≤ 5 }} but still prints the\nunderlying function.  The delaborators below close the loop for the common\ncases: Hoare triples, ->> implications, and assertion substitutions are\nprinted back in their concrete notation, and an assertion Lean cannot\nrebuild falls back to the ~ escape (or, ultimately, to the raw term).  As\nbefore, there is no need to understand the details, and everything can be\nswitched off with set_option pp.notation false.\n\n-- TODO xhalo32: this all needs to be reworked\n-- ::::details (summary := \"Notation encoding: printing assertions back\")\n-- lean\n-- namespace Assn.Delab\n-- open Lean PrettyPrinter Delaborator SubExpr Parenthesizer Imp.Delab\n\n-- /-- Re-inserts parentheses in `assn_aexp` output according to the grammar's\n-- precedences. -/\n-- @[category_parenthesizer assn_aexp]\n-- def assn_aexp.parenthesizer : CategoryParenthesizer | prec => do\n--   maybeParenthesize `assn_aexp true wrapParens prec <|\n--     parenthesizeCategoryCore `assn_aexp prec\n-- where\n--   wrapParens (stx : Syntax) : Syntax := Unhygienic.run do\n--     let pstx ← `(assn_aexp| ($(⟨stx⟩)))\n--     return pstx.raw.setInfo (SourceInfo.fromRef stx)\n\n-- /-- Re-inserts parentheses in `assn` output according to the grammar's\n-- precedences. -/\n-- @[category_parenthesizer assn]\n-- def assn.parenthesizer : CategoryParenthesizer | prec => do\n--   maybeParenthesize `assn true wrapParens prec <|\n--     parenthesizeCategoryCore `assn prec\n-- where\n--   wrapParens (stx : Syntax) : Syntax := Unhygienic.run do\n--     let pstx ← `(assn| ($(⟨stx⟩)))\n--     return pstx.raw.setInfo (SourceInfo.fromRef stx)\n\n-- /-- Print the focused term as a bare identifier if it delaborates to one,\n-- and with the `~` escape otherwise. -/\n-- def identOrEscapeAexp : DelabM (TSyntax `assn_aexp) := do\n--   match ← delab with\n--   | `($x:ident) => `(assn_aexp| $x:ident)\n--   | t => `(assn_aexp| ~$t)\n\n-- /-- Print the focused term as a bare identifier if it delaborates to one,\n-- and with the `~` escape otherwise. -/\n-- def identOrEscapeAssn : DelabM (TSyntax `assn) := do\n--   match ← delab with\n--   | `($x:ident) => `(assn| $x:ident)\n--   | t => `(assn| ~$t)\n\n-- /-- Rebuild `assn_aexp` syntax from an `Aexp` (the argument of the\n-- `Aexp'.ofAexp` coercion). -/\n-- partial def delabAexpAsAssn : DelabM (TSyntax `assn_aexp) := do\n--   let stx ←\n--     match_expr ← getExpr with\n--     | Aexp.num _ =>\n--       match (← withAppArg getExpr).nat? with\n--       | some v => pure ⟨Syntax.mkNumLit (toString v) |>.raw⟩\n--       | none => identOrEscapeAexp\n--     | Aexp.id _ =>\n--       match ← withAppArg getExpr with\n--       | .const nm _ => `(assn_aexp| $(mkIdent nm):ident)\n--       | _ => identOrEscapeAexp\n--     | Aexp.plus _ _ =>\n--       let s1 ← withAppFn <| withAppArg delabAexpAsAssn\n--       let s2 ← withAppArg delabAexpAsAssn\n--       `(assn_aexp| $s1 + $s2)\n--     | Aexp.minus _ _ =>\n--       let s1 ← withAppFn <| withAppArg delabAexpAsAssn\n--       let s2 ← withAppArg delabAexpAsAssn\n--       `(assn_aexp| $s1 - $s2)\n--     | Aexp.mult _ _ =>\n--       let s1 ← withAppFn <| withAppArg delabAexpAsAssn\n--       let s2 ← withAppArg delabAexpAsAssn\n--       `(assn_aexp| $s1 * $s2)\n--     | _ => identOrEscapeAexp\n--   annAsTerm stx\n\n-- mutual\n\n-- /-- Rebuild `assn_aexp` syntax from an assertion-level numeric value -- the\n-- body form the `{{ … }}` macros produce, applied to the state variable. -/\n-- partial def delabAssnAexpVal : DelabM (TSyntax `assn_aexp) := do\n--   let e ← getExpr\n--   let stx ←\n--     match_expr e with\n--     | HAdd.hAdd _ _ _ _ _ _ =>\n--       let s1 ← withNaryArg 4 delabAssnAexpVal\n--       let s2 ← withNaryArg 5 delabAssnAexpVal\n--       `(assn_aexp| $s1 + $s2)\n--     | HSub.hSub _ _ _ _ _ _ =>\n--       let s1 ← withNaryArg 4 delabAssnAexpVal\n--       let s2 ← withNaryArg 5 delabAssnAexpVal\n--       `(assn_aexp| $s1 - $s2)\n--     | HMul.hMul _ _ _ _ _ _ =>\n--       let s1 ← withNaryArg 4 delabAssnAexpVal\n--       let s2 ← withNaryArg 5 delabAssnAexpVal\n--       `(assn_aexp| $s1 * $s2)\n--     | _ =>\n--       let .app f v := e | failure\n--       guard v.isFVar\n--       match_expr f with\n--       | Aexp'.ofNat _ =>\n--         match (← withAppFn <| withAppArg getExpr).nat? with\n--         | some val => pure ⟨Syntax.mkNumLit (toString val) |>.raw⟩\n--         | none => withAppFn <| withAppArg identOrEscapeAexp\n--       | Aexp'.ofAexp _ => withAppFn <| withAppArg delabAexpAsAssn\n--       | _ =>\n--         if f.isLambda then\n--           withAppFn do withBindingBody (← getExpr).bindingName! delabAssnAexpVal\n--         else\n--           withAppFn identOrEscapeAexp\n--   annAsTerm stx\n\n-- /-- Rebuild `assn` syntax from an assertion body -- the proposition the\n-- `{{ … }}` macros produce, applied to the state variable. -/\n-- partial def delabAssnVal : DelabM (TSyntax `assn) := do\n--   let e ← getExpr\n--   let stx ←\n--     match_expr e with\n--     | Eq _ _ _ =>\n--       let s1 ← withNaryArg 1 delabAssnAexpVal\n--       let s2 ← withNaryArg 2 delabAssnAexpVal\n--       `(assn| $s1:assn_aexp = $s2:assn_aexp)\n--     | Ne _ _ _ =>\n--       let s1 ← withNaryArg 1 delabAssnAexpVal\n--       let s2 ← withNaryArg 2 delabAssnAexpVal\n--       `(assn| $s1:assn_aexp ≠ $s2:assn_aexp)\n--     | LE.le _ _ _ _ =>\n--       let s1 ← withNaryArg 2 delabAssnAexpVal\n--       let s2 ← withNaryArg 3 delabAssnAexpVal\n--       `(assn| $s1:assn_aexp ≤ $s2:assn_aexp)\n--     | LT.lt _ _ _ _ =>\n--       let s1 ← withNaryArg 2 delabAssnAexpVal\n--       let s2 ← withNaryArg 3 delabAssnAexpVal\n--       `(assn| $s1:assn_aexp < $s2:assn_aexp)\n--     | GE.ge _ _ _ _ =>\n--       let s1 ← withNaryArg 2 delabAssnAexpVal\n--       let s2 ← withNaryArg 3 delabAssnAexpVal\n--       `(assn| $s1:assn_aexp ≥ $s2:assn_aexp)\n--     | GT.gt _ _ _ _ =>\n--       let s1 ← withNaryArg 2 delabAssnAexpVal\n--       let s2 ← withNaryArg 3 delabAssnAexpVal\n--       `(assn| $s1:assn_aexp > $s2:assn_aexp)\n--     | And _ _ =>\n--       let s1 ← withNaryArg 0 delabAssnVal\n--       let s2 ← withNaryArg 1 delabAssnVal\n--       `(assn| $s1 ∧ $s2)\n--     | Or _ _ =>\n--       let s1 ← withNaryArg 0 delabAssnVal\n--       let s2 ← withNaryArg 1 delabAssnVal\n--       `(assn| $s1 ∨ $s2)\n--     | Iff _ _ =>\n--       let s1 ← withNaryArg 0 delabAssnVal\n--       let s2 ← withNaryArg 1 delabAssnVal\n--       `(assn| $s1 ↔ $s2)\n--     | Not _ =>\n--       `(assn| ¬$(← withAppArg delabAssnVal))\n--     | _ =>\n--       if e.isArrow then\n--         let s1 ← withBindingDomain delabAssnVal\n--         let s2 ← withBindingBody e.bindingName! delabAssnVal\n--         `(assn| $s1 → $s2)\n--       else\n--         let .app f v := e | failure\n--         guard v.isFVar\n--         match_expr f with\n--         | Assertion.ofProp _ =>\n--           match ← withAppFn <| withAppArg getExpr with\n--           | .const nm _ => `(assn| $(mkIdent nm):ident)\n--           | _ => withAppFn <| withAppArg identOrEscapeAssn\n--         | Assertion.sub _ _ _ => withAppFn delabSubInner\n--         | _ =>\n--           if f.isLambda then\n--             withAppFn do withBindingBody (← getExpr).bindingName! delabAssnVal\n--           else\n--             withAppFn identOrEscapeAssn\n--   annAsTerm stx\n\n-- /-- Rebuild the substitution notation from an `Assertion.sub` application. -/\n-- partial def delabSubInner : DelabM (TSyntax `assn) := do\n--   let .const nm _ ← withNaryArg 0 getExpr | failure\n--   let a ← withNaryArg 1 delabAexpInner\n--   let P ← withNaryArg 2 delabAssnFun\n--   `(assn| $P [$(mkIdent nm):ident ↦ $a:imp_aexp])\n\n-- /-- Rebuild `assn` syntax from an `Assertion`-valued term. -/\n-- partial def delabAssnFun : DelabM (TSyntax `assn) := do\n--   let e ← getExpr\n--   let stx ←\n--     match_expr e with\n--     | Assertion.ofProp _ =>\n--       match ← withAppArg getExpr with\n--       | .const nm _ => `(assn| $(mkIdent nm):ident)\n--       | _ => withAppArg identOrEscapeAssn\n--     | Assertion.sub _ _ _ => delabSubInner\n--     | _ =>\n--       if e.isLambda then\n--         withBindingBody e.bindingName! delabAssnVal\n--       else\n--         identOrEscapeAssn\n--   annAsTerm stx\n\n-- end\n\n-- /-- Rebuild `assn` syntax from an `Assertion`, falling back to the escaped\n-- raw term. -/\n-- def delabAssnTotal : DelabM (TSyntax `assn) :=\n--   delabAssnFun <|> identOrEscapeAssn\n-- \n-- ::::\n\n-- ::::details (summary := \"Notation encoding: registering the delaborators\")\n-- lean\n-- @[delab app.ValidHoareTriple]\n-- def delabTriple : Delab := whenPPOption getPPNotation do\n--   guard <| (← getExpr).isAppOfArity ``ValidHoareTriple 3\n--   let P ← withNaryArg 0 delabAssnTotal\n--   let c ← withNaryArg 1 delabComInner\n--   let Q ← withNaryArg 2 delabAssnTotal\n--   `({{ $P }} $c:imp_com {{ $Q }})\n\n-- @[delab app.AssertImplies]\n-- def delabAssertImplies : Delab := whenPPOption getPPNotation do\n--   guard <| (← getExpr).isAppOfArity ``AssertImplies 2\n--   let P ← withNaryArg 0 delabAssnTotal\n--   let Q ← withNaryArg 1 delabAssnTotal\n--   `({{ $P }} ->> {{ $Q }})\n\n-- @[delab app.Assertion.sub]\n-- def delabSub : Delab := whenPPOption getPPNotation do\n--   guard <| (← getExpr).isAppOfArity ``Assertion.sub 3\n--   `({{ $(← delabSubInner) }})\n\n-- @[delab app.Assertion.ofProp]\n-- def delabOfProp : Delab := whenPPOption getPPNotation do\n--   guard <| (← getExpr).isAppOfArity ``Assertion.ofProp 1\n--   `({{ $(← delabAssnFun) }})\n\n-- end Assn.Delab\n-- \n-- ::::\n\n\n\n\n\nNow, using the substitution operation we've just defined, we can\ngive the precise proof rule for assignment:\n\n---------------------------- (hoare_asgn)\n{{Q [X ↦ a]}} X := a {{Q}}\n\n\nWe can prove formally that this rule is indeed valid.\n\ntheorem hoare_asgn (Q : Assertion) (x : Ident) (a : Aexp) :\n    {{ Q [x ↦ ~a] }}  x := ~a; {{ Q }} := by\n  intro st st' hE hQ\n  inversion hE with\n  | asgn n h =>\n    subst h\n    exact hQ\n\n\n\n\nHere's a first formal proof of a Hoare triple using this rule.\n\ntheorem assertion_sub_example :\n    {{ {{ X < 5 }} [X ↦ X + 1] }}\n      X := X + 1;\n    {{ X < 5 }} := by\n  apply hoare_asgn\n\n\n\n\nOf course, we'd probably prefer to work with this simpler triple:\n\n{{X < 4}} X := X + 1 {{X < 5}}\n\n\nWe will see how to do so in the next section.\n\nSeveral proofs below use the facts about total-map updates\nproved in the Typeclasses chapter -- TotalMap.update_eq,\nTotalMap.update_neq, TotalMap.update_shadow, TotalMap.update_same,\nand TotalMap.update_permute.  Make sure you understand their statements.\n\nComplete these Hoare triples by providing an appropriate\nprecondition using exists, then prove then with apply\nhoare_asgn. If you find that tactic doesn't suffice, double check\nthat you have completed the triple properly.theorem hoare_asgn_examples1 :\n    ∃ P : Assertion,\n      {{ P }}\n        X := 2 * X;\n      {{ X ≤ 10 }} := by\n  solution!\n    exists {{ X ≤ 10 }} [X ↦ 2 * X]\n    apply hoare_asgn\ntheorem hoare_asgn_examples2 :\n    ∃ P : Assertion,\n      {{ P }}\n        X := 3;\n      {{ 0 ≤ X ∧ X ≤ 5 }} := by\n  solution!\n    exists {{ 0 ≤ X ∧ X ≤ 5 }} [X ↦ 3]\n    apply hoare_asgn\nThe assignment rule looks backward to almost everyone the first\ntime they see it.  If it still seems puzzling to you, it may help\nto think a little about alternative \"forward\" rules.  Here is a\nseemingly natural one:------------------------------ (hoare_asgn_wrong)\n{{ True }} X := a {{ X = a }}\nGive a counterexample showing that this rule is incorrect and use\nit to complete the proof below, showing that it is really a\ncounterexample.  (Hint: The rule universally quantifies over the\narithmetic expression a, so your counterexample needs to\nexhibit an a for which the rule doesn't work.)theorem hoare_asgn_wrong : ∃ a : Aexp,\n    ¬ {{ True }} X := ~a; {{ X = a }} := by\n  solution!\n    exists aexp { X + 1 }\n    intro hc\n    unfold ValidHoareTriple at hc\n    have h2 : (X →ₜ 1 ; ∅)[X] = (aexp { X + 1 }).eval (X →ₜ 1 ; ∅) := by\n      apply hc ∅ (X →ₜ 1 ; ∅)\n      · apply Com.EvalR.asgn; rfl\n      · exact True.intro\n    simp [TotalMap.update_eq] at h2\nIf a itself mentions X, then the value of a may be different\nin the final state because of this update. For example, if a is\nX + 1, then setting X to a certainly does not achieve the\npostcondition X = X + 1!  The underlying problem is that the\nstate in which the postcondition will be checked is different than\nthe state in which a was evaluated when it was assigned to X.It sure would be great for the next two exercises\nto use the updated notation.  However, I can't figure out how to\nget the postcondition to work with it.  The problem is that the\nsubstitution operator is defined on assertions, but I need a\nversion of it defined on expressions.\nLef 21: Gave it another unsuccessful go, seems like the same\nissue as MRC'20.\n\n  Theorem hoare_asgn_fwd :\n         ∀ P m a,\n           {{ P ∧ X = m }}\n           X := a\n           {{ P [X ↦ m] ∧ X = a }}.\nBy using a parameter m (a Lean number) to remember the\noriginal value of X we can define a Hoare rule for assignment\nthat does, intuitively, \"work forwards\" rather than backwards.------------------------------------------ (hoare_asgn_fwd)\n{{fun st => P st ∧ st[X] = m}}\n  X := a\n{{fun st => P (X →ₜ m ; st) ∧ st[X] = Aexp.eval (X →ₜ m ; st) a }}\nNote that we need to write out the postcondition in \"desugared\"\nform, because it needs to talk about two different states: we use\nthe original value of X to reconstruct the state st' before the\nassignment took place.  (Also note that this rule is more complicated\nthan hoare_asgn!)Prove that this rule is correct.HIDE: BCP 21: Could we make the precondition use compact\nnotation, at least?HIDE: SAZ 2024 - this version of the syntax does let\nus use the compact notation for the precondition, but it\ncomes at the cost of having to \"escape\" the function in\nthe postcondition.theorem hoare_asgn_fwd (m : Nat) (a : Aexp) (P : Assertion) :\n    {{ P ∧ X = m }}\n      X := ~a;\n    {{ fun st => P (X →ₜ m ; st)\n         ∧ st[X] = a.eval (X →ₜ m ; st) }} := by\n  solution!\n    unfold ValidHoareTriple\n    intro st st' heval hpre\n    inversion heval with\n    | asgn n h =>\n      obtain ⟨hp, hx⟩ := hpre\n      subst h\n      have hx' : st[X] = m := hx\n      rw [← hx', TotalMap.update_eq, TotalMap.update_shadow,\n          TotalMap.update_same]\n      exact ⟨hp, rfl⟩\nAnother way to define a forward rule for assignment is to\nexistentially quantify over the previous value of the assigned\nvariable.  Prove that it is correct.------------------------------------ (hoare_asgn_fwd_exists)\n{{fun st => P st}}\n  X := a\n{{fun st => ∃ m, P (X →ₜ m ; st) ∧\n               st[X] = Aexp.eval (X →ₜ m ; st) a }}\ntheorem hoare_asgn_fwd_exists (a : Aexp) (P : Assertion) :\n    {{ P }}\n      X := ~a;\n    {{ fun st => ∃ m, P (X →ₜ m ; st) ∧\n         st[X] = a.eval (X →ₜ m ; st) }} := by\n  solution!\n    unfold ValidHoareTriple\n    intro st st' heval hpre\n    inversion heval with\n    | asgn n h =>\n      subst h\n      exists st[X]\n      rw [TotalMap.update_eq, TotalMap.update_shadow, TotalMap.update_same]\n      exact ⟨hpre, rfl⟩\n\n\n\n\n","context":"Hoare Logic\u0009Hoare: Hoare Logic, Part I\u0009Proof Rules","header":"4.4.4. Printing Assertions","id":"/Hoare/#assn-delaborators"}});